//! NN op numerics vs tinygrad goldens: conv2d (incl. groups/stride/dilation/
//! padding), max_pool2d (incl. ceil_mode and return_indices), one_hot, and
//! sparse_categorical_crossentropy.
//!
//! `tests/nn_golden.rs` is generated by `py/dump_nn_golden.py`.

use autorust::tensor::Tensor;
use autorust::uop::ctx::UOpCtx;

mod nn_golden;
use nn_golden::{CONV_GOLDEN, CE_GOLDEN, ONE_HOT_GOLDEN, POOL_GOLDEN};

fn close(got: &[f32], want: &[f32], rtol: f32, name: &str) {
    assert_eq!(got.len(), want.len(), "{name}: length {} != {}", got.len(), want.len());
    for (i, (a, b)) in got.iter().zip(want.iter()).enumerate() {
        let tol = rtol * b.abs().max(1.0);
        assert!((a - b).abs() <= tol, "{name}[{i}]: got {a}, want {b} (diff {}, tol {tol})", (a - b).abs());
    }
}

#[test]
fn conv2d_matches_tinygrad() {
    for c in CONV_GOLDEN {
        let mut ctx = UOpCtx::new();
        let mut sess = autorust::engine::session::Session::new();
        let x = Tensor::from_slice(&mut ctx, c.x, None, None).reshape(&mut ctx, c.x_shape);
        let w = Tensor::from_slice(&mut ctx, c.w, None, None).reshape(&mut ctx, c.w_shape);
        let bias = if c.bias.is_empty() { None } else { Some(Tensor::from_slice(&mut ctx, c.bias, None, None)) };
        let out = x.conv2d(&mut ctx, &w, bias.as_ref(), c.groups, c.stride, c.dilation, c.padding, None);
        assert_eq!(out.shape(&mut ctx).as_slice().iter().map(|s| s.clone().as_i64().unwrap_or(0) as usize).collect::<Vec<_>>(), c.out_shape.to_vec(), "{}: shape", c.name);
        let got = out.to_list::<f32>(&mut ctx, &mut sess);
        close(&got, c.out, 1e-4, c.name);
    }
}

#[test]
fn max_pool2d_matches_tinygrad() {
    for p in POOL_GOLDEN {
        let mut ctx = UOpCtx::new();
        let mut sess = autorust::engine::session::Session::new();
        let x = Tensor::from_slice(&mut ctx, p.x, None, None).reshape(&mut ctx, p.x_shape);
        let stride = if p.stride.is_empty() { None } else { Some(p.stride) };
        let (out, idx) = x.max_pool2d(&mut ctx, p.k, stride, p.dilation, p.padding, p.ceil_mode, p.return_indices);
        let got_shape: Vec<usize> = out.shape(&mut ctx).as_slice().iter().map(|s| s.clone().as_i64().unwrap_or(0) as usize).collect();
        assert_eq!(got_shape, p.out_shape.to_vec(), "{}: shape", p.name);
        let got = out.to_list::<f32>(&mut ctx, &mut sess);
        close(&got, p.out, 1e-5, p.name);
        if p.return_indices {
            let idx = idx.expect("return_indices");
            let idx_shape: Vec<usize> = idx.shape(&mut ctx).as_slice().iter().map(|s| s.clone().as_i64().unwrap_or(0) as usize).collect();
            assert_eq!(idx_shape, p.idx_shape.to_vec(), "{}: idx shape", p.name);
            let got_idx = idx.to_list::<f32>(&mut ctx, &mut sess);
            close(&got_idx, p.idx, 0.0, p.name);
        }
    }
}

#[test]
fn sparse_categorical_crossentropy_matches_tinygrad() {
    for c in CE_GOLDEN {
        let mut ctx = UOpCtx::new();
        let mut sess = autorust::engine::session::Session::new();
        let logits = Tensor::from_slice(&mut ctx, c.logits, None, None).reshape(&mut ctx, c.logits_shape);
        let y = Tensor::from_slice(&mut ctx, c.y, None, None);
        let out = logits.sparse_categorical_crossentropy(&mut ctx, &y, c.ignore_index, c.label_smoothing, c.reduction);
        let got = out.to_list::<f32>(&mut ctx, &mut sess);
        close(&got, c.out, 1e-4, c.name);
    }
}

#[test]
fn one_hot_matches_tinygrad() {
    for o in ONE_HOT_GOLDEN {
        let mut ctx = UOpCtx::new();
        let mut sess = autorust::engine::session::Session::new();
        let x = Tensor::from_slice(&mut ctx, o.x, None, None);
        let out = x.one_hot(&mut ctx, o.num_classes);
        assert_eq!(out.shape(&mut ctx).as_slice().iter().map(|s| s.clone().as_i64().unwrap_or(0) as usize).collect::<Vec<_>>(), o.out_shape.to_vec(), "{}: shape", o.name);
        let got = out.to_list::<f32>(&mut ctx, &mut sess);
        close(&got, o.out, 0.0, o.name);
    }
}